# -*- coding: utf-8 -*-
"""抖音补充包引导：把 runtime/pkgs/mediacrawler 作为附加 site 目录加载。

默认只挂 mediacrawler 一组；若外部设置了 MD_PKG_GROUPS 则按它指定的组挂载
（与 3.12 运行时的 sitecustomize 保持同一套约定）。
"""
import os
import re
import site

_HERE = os.path.dirname(os.path.abspath(__file__))
_RUNTIME = os.path.dirname(os.path.dirname(os.path.dirname(_HERE)))
_PKGS = os.path.join(_RUNTIME, "pkgs")

_want = os.environ.get("MD_PKG_GROUPS", "").strip()
_names = [n for n in re.split(r"[;,]", _want) if n.strip()] if _want else ["mediacrawler"]

for _name in _names:
    _dir = os.path.join(_PKGS, _name.strip())
    if os.path.isdir(_dir):
        site.addsitedir(_dir)